INSERT INTO public.recruiter_weeks (week_number, quarter, topic, focus, fact) VALUES
(1,1,'Intake meeting mastery','Turning a hiring manager wishlist into real capabilities','Roles with a written intake agreement fill roughly 30% faster than those opened from a job description alone.'),
(2,1,'Force-ranking must-haves','Separating non-negotiables from trainable skills','Requisitions with more than eight "must-have" requirements see a sharp drop in qualified applicant flow.'),
(3,1,'Benchmark profiles and calibration','Agreeing on three reference profiles before sourcing','Calibrating on real profiles up front cuts rejected-shortlist loops by about half.'),
(4,1,'Boolean fundamentals','Precision search strings that surface real signal','Adding a single well-chosen NOT term can remove a third of irrelevant search noise.'),
(5,1,'Semantic and skills-based search','Searching for capability, not job titles','Skills-based search consistently surfaces candidates that title-based search never returns.'),
(6,1,'Precision versus wide-net outreach','Choosing the right sourcing strategy per role','Narrow, well-targeted outreach typically converts three to five times better than mass sends.'),
(7,1,'Talent market mapping','Understanding where the talent actually sits','A market map turns "no one is out there" into a countable, negotiable number.'),
(8,1,'Salary calibration','Grounding pay expectations in market data','Roles priced below the 40th percentile take substantially longer to close.'),
(9,1,'Candidate scarcity and pipeline realism','Setting honest expectations with stakeholders','Scarcity should change the process design, not just the outreach volume.'),
(10,1,'Screening frameworks','Spotting true signal versus resume buzzwords','Structured screens roughly double the predictive value of a first conversation.'),
(11,1,'Reading career patterns','Evidence over pedigree in resume review','Tenure patterns predict less than scope and impact progression.'),
(12,1,'Structured phone screens','Designing a repeatable 20-minute screen','Asking every candidate the same core questions makes screens comparable.'),
(13,1,'Q1 capstone: intake to shortlist','Running the full front end of a search','The strongest recruiters treat intake, search and screening as one connected system.'),
(14,2,'Cold outreach hooks','Opening lines that earn a reply','Personalised first lines lift reply rates far more than longer messages do.'),
(15,2,'Candidate value proposition','Selling the role honestly and specifically','Candidates respond to problems to solve, not adjectives about culture.'),
(16,2,'Subject lines and channel testing','Testing what actually gets opened','Small, disciplined tests beat rewriting every message from scratch.'),
(17,2,'Sequencing and follow-up cadence','Persistence without pestering','Most positive replies to outbound arrive on the second or third touch.'),
(18,2,'Compensation objections','Handling pay expectations early and honestly','Discussing range in the first conversation prevents most late-stage collapses.'),
(19,2,'Remote and hybrid objections','Navigating location policy conversations','Clarity about policy loses fewer candidates than vagueness does.'),
(20,2,'Career pivot conversations','Assessing and supporting non-linear moves','Pivot candidates need evidence of transferable capability, not enthusiasm alone.'),
(21,2,'Objections that need the hiring manager','Knowing when to bring the manager in','A five-minute manager call rescues offers that recruiters alone cannot.'),
(22,2,'Candidate experience fundamentals','Designing a process people speak well of','Most candidate complaints are about silence, not rejection.'),
(23,2,'Preventing ghosting','Transparent updates and reliable timelines','A promised update delivered on time is worth more than a fast process.'),
(24,2,'Delivering feedback and rejections','Saying no in a way that keeps the door open','Specific, kind rejection feedback measurably improves employer reputation.'),
(25,2,'Nurturing silver medallists','Keeping strong runners-up warm','Silver medallists are among the highest-converting sources for future roles.'),
(26,2,'Q2 capstone: outreach to commitment','Running engagement end to end','Conversion is built across the whole journey, not at the offer stage.'),
(27,3,'Behavioural deep dives','Getting real evidence in fifteen minutes','Two well-probed examples beat six shallow questions.'),
(28,3,'Validating STAR answers','Checking the result was actually theirs','The "what did you personally do" follow-up separates owners from observers.'),
(29,3,'Probing without leading','Questions that do not hand over the answer','Leading questions contaminate the evidence you are trying to collect.'),
(30,3,'Consistent screen scoring','Scoring against anchors, not impressions','Wide score spread between screeners usually means undefined anchors.'),
(31,3,'Affinity bias in sourcing','Noticing who you naturally reach out to','Sourcing bias is set long before the interview panel meets anyone.'),
(32,3,'Prestige and pedigree bias','Separating brand names from capability','Employer brand on a CV is a weak predictor of on-the-job performance.'),
(33,3,'Career gaps and non-linear paths','Assessing what people can do now','Gaps carry far less signal than the work either side of them.'),
(34,3,'Inclusive shortlists','Building slates that widen the evidence base','Diverse slates only help when the evaluation criteria are structured.'),
(35,3,'Screening technical depth','Assessing skill without being an engineer','Good non-technical screens test reasoning and trade-offs, not syntax.'),
(36,3,'Non-traditional career paths','Evaluating bootcamp, self-taught and adjacent talent','Work samples level the field between traditional and non-traditional routes.'),
(37,3,'Work samples and evidence','Choosing assessments that predict performance','Job-relevant work samples remain among the most predictive tools available.'),
(38,3,'Calibrating with interviewers','Aligning your screen with the technical loop','Recruiter-interviewer calibration cuts wasted onsite time dramatically.'),
(39,3,'Q3 capstone: bias-resistant assessment','Running a fair, structured evaluation','Fairness and accuracy are the same project, not competing ones.'),
(40,4,'Offer pre-closing','Testing commitment before the offer is issued','Offers that are pre-closed are accepted far more often than those that are not.'),
(41,4,'Counter-offer risk','Uncovering the risks candidates do not volunteer','Most counter-offer acceptances were predictable weeks earlier.'),
(42,4,'Expectation anchoring','Managing numbers throughout the process','Anchors set early are much harder to move at offer stage.'),
(43,4,'Motivation mapping','Understanding what really drives the decision','Money is rarely the only reason a strong candidate moves.'),
(44,4,'Salary negotiation','Negotiating within a real budget','Preparation, not improvisation, is what wins negotiations.'),
(45,4,'Equity education','Explaining ownership clearly and honestly','Candidates undervalue equity they do not understand.'),
(46,4,'Competitive package structuring','Building the best offer the budget allows','Non-cash levers often close the gap when base salary cannot.'),
(47,4,'Multiple offers and deadlines','Competing without pressuring','Exploding deadlines damage brand more often than they win candidates.'),
(48,4,'Hiring manager calibration','Keeping the partnership aligned week to week','Weekly calibration reduces rejected shortlists more than better sourcing does.'),
(49,4,'SLA management','Accelerating feedback loops','Feedback delays are the single most common cause of lost candidates.'),
(50,4,'Re-engaging dormant managers','Moving stalled searches forward','Data, not chasing, is what restarts a stalled requisition.'),
(51,4,'Funnel diagnostics','Reading recruiting data to find the real bottleneck','Conversion rates between stages tell you where a search is actually failing.'),
(52,4,'Q4 capstone: strategic talent partnership','Operating as an advisor, not an order taker','Recruiters who bring evidence to the table change hiring decisions.')
